python3 << 'EOF'
import json

with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Search all pages for individual income tax data in tables
if 'document' in data and 'pages' in data['document']:
    pages = data['document']['pages']

    # Look for tables with 'individual' in them
    for i, page in enumerate(pages):
        if 'tables' in page:
            for j, table in enumerate(page['tables']):
                table_str = str(table)
                if 'individual' in table_str.lower() and 'income' in table_str.lower():
                    print(f"Page {i}, Table {j}: Found individual income data")
                    # Print the table headers if available
                    if 'headers' in table:
                        print("Headers:", table['headers'][:5])
